#include "all_your_base.h"

namespace all_your_base {

std::vector<unsigned long> convert(unsigned long input_base,
                                   std::vector<unsigned long> input_digits,
                                   unsigned long output_base) {
    if (input_base < 2 || output_base < 2 || input_digits.empty()) {
        return {};
    }

    for (const auto digit : input_digits) {
        if (digit >= input_base) {
            return {};
        }
    }

    std::vector<unsigned long> output_digits{0};

    for (const auto digit : input_digits) {
        unsigned long carry = digit;

        for (auto output_digit = output_digits.rbegin();
             output_digit != output_digits.rend();
             ++output_digit) {
            const unsigned long product =
                (*output_digit * input_base) + carry;
            *output_digit = product % output_base;
            carry = product / output_base;
        }

        while (carry > 0) {
            output_digits.insert(output_digits.begin(), carry % output_base);
            carry /= output_base;
        }
    }

    return output_digits;
}

}  // namespace all_your_base
